class Solution {
public:
    long long maximumSubarraySum(vector<int>& nums, int k) {
        unordered_map<long long, long long> minPrefix;
        long long prefix = 0;
        long long ans = LLONG_MIN;
        for (int j = 0, n = nums.size(); j < n; j++) {
            long long val = nums[j];
            auto it1 = minPrefix.find(val - k);
            if (it1 != minPrefix.end())
                ans = max(ans, prefix + val - it1->second);
            auto it2 = minPrefix.find(val + k);
            if (it2 != minPrefix.end())
                ans = max(ans, prefix + val - it2->second);
            auto it = minPrefix.find(val);
            if (it != minPrefix.end())
                it->second = min(it->second, prefix);
            else
                minPrefix[val] = prefix;
            prefix += val;
        }
        return ans == LLONG_MIN ? 0 : ans;
    }
};
